insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,metadata) values ('ulisse','dundrum','core','Dundrum','Dublin','area',13,'2026-11-05','Representative geographic point','Mulligan mentions Dundrum in his joke about Haines’s book.','Representative locality coordinate; no scene is set at this point.','ea0aadb2fd46f90e4d0192277105466bbcbb4ff75f17eb222b8740a60a5900a5','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-05","texts":{"it":"Dundrum è la località a sud di Dublino evocata da Mulligan nella battuta sul libro di Haines. Il punto rappresenta la località.","en":"Dundrum is the locality south of Dublin evoked by Mulligan in his joke about Haines’s book. The point represents the locality.","fr":"Dundrum est la localité au sud de Dublin évoquée par Mulligan dans sa plaisanterie sur le livre de Haines. Le point représente la localité.","es":"Dundrum es la localidad al sur de Dublín evocada por Mulligan en su broma sobre el libro de Haines. El punto representa la localidad."}}}'::jsonb) on conflict do nothing;
