insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:library',1,'library','core',3,'mentioned','Haines says he intends to visit the National Library later that day.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{}') on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:tower:original',1,'1:core:tower','original','en','original','He pointed his finger in friendly jest and went over to the parapet, laughing to himself. Stephen Dedalus stepped up, followed him wearily halfway and sat down on the edge of the gunrest, watching him still as he propped his mirror on the parapet, dipped the brush in the bowl and lathered cheeks and neck.','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["parapet","gunrest"],"reviewedAt":"2026-11-05"}'::jsonb) on conflict(book_id,id) do update set quote=excluded.quote,attribution=excluded.attribution,text_source_id=excluded.text_source_id,metadata=public.excerpts.metadata||excluded.metadata;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:forty:original',1,'1:core:forty','original','en','original','He capered before them down towards the fortyfoot hole, fluttering his winglike hands, leaping nimbly, Mercury’s hat quivering in the fresh wind that bore back to them his brief birdlike cries.
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:dundrum:original',1,'1:core:dundrum','original','en','original','—That’s folk, he said very earnestly, for your book, Haines. Five lines of text and ten pages of notes about the folk and the fishgods of Dundrum. Printed by the weird sisters in the year of the big wind.','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Dundrum"],"reviewedAt":"2026-11-05"}'::jsonb) on conflict(book_id,id) do update set quote=excluded.quote,attribution=excluded.attribution,text_source_id=excluded.text_source_id,metadata=public.excerpts.metadata||excluded.metadata;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:library:original',1,'1:core:library','original','en','original','—Seriously, Dedalus. I’m stony. Hurry out to your school kip and bring us back some money. Today the bards must drink and junket. Ireland expects that every man this day will do his duty.
